function fieldMarkup(f,c,value){const key=f.key,id='op-'+key,v=value??f.value??'',required=f.required?'required':'';if(f.photoEntry)return `<div class="field"><label class="ws-upload" for="${id}"><span class="ws-upload-icon" aria-hidden="true"><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="3" y="4" width="18" height="16" rx="3"/><circle cx="9" cy="9" r="1.4"/><path d="m4 17 5-5 4 4 3-3 4 4"/></svg></span><span>${esc(f.label)}</span><img ${v?'src="'+esc(v)+'"':'hidden'} alt="پیش‌نمایش"><input id="${id}" type="file" name="${key}" accept="image/*" ${required}></label></div>`;if(f.kind==='invoiceRows')return `<details class="op-repeat" data-kind="invoiceRows"><summary>جزئیات ردیف‌ها · اختیاری</summary><div data-repeat-items>${(Array.isArray(v)?v:[]).map((line,i)=>repeatRow(f.kind,i,c,line)).join('')}</div>${button('افزودن قلم','add-row','data-kind="invoiceRows"','text-link')}</details>`;if(['receiptRows','sourceRows','outputRows'].includes(f.kind))return `<section class="op-repeat" data-kind="${f.kind}"><h3>${f.label}</h3><div data-repeat-items>${(Array.isArray(v)&&v.length?v:[{}]).map((r,i)=>repeatRow(f.kind,i,c,r)).join('')}</div>${button('ردیف دیگر','add-row',`data-kind="${f.kind}"`,'text-link')}</section>`;if(f.kind==='scores')return `<fieldset class="op-scores"><legend>${f.label}</legend>${['دقت','وقت‌شناسی','همکاری','ایمنی','کیفیت','مسئولیت‌پذیری'].map(x=>`<label>${x}<input type="number" name="score.${x}" min="0" max="5" step="0.1" placeholder="ثبت نشده" value="${esc(v?.[x]??'')}"></label>`).join('')}<small>ثبت دستی ارزیابی مدیر؛ این بخش در کارنامه کارمند نمایش داده نمی‌شود.</small></fieldset>`;
 const common=`id="${id}" name="${key}" ${required}`;
 let input=f.kind==='textarea'?`<textarea ${common}>${esc(v)}</textarea>`:f.kind==='select'||f.kind==='multiselect'?`<select ${common} ${f.kind==='multiselect'?'multiple':''}><option value="">انتخاب کنید</option>${(f.options||[]).map(o=>`<option value="${esc(o.value)}" ${(Array.isArray(v)?v.includes(o.value):String(v)===String(o.value))?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`:f.kind==='checkbox'?`<input ${common} type="checkbox" value="yes" ${v===true?'checked':''}>`:`<input ${common} type="${f.kind==='number'?'text':f.kind==='file'?'file':f.kind}" ${f.kind==='number'?'inputmode="decimal"':''} ${f.kind==='file'?`accept="image/*,.pdf" ${f.camera?'capture="environment"':''}`:`value="${esc(v)}"`}>`;
 return `<div class="field"><label for="${id}">${esc(f.label)}${f.required?' <span class="required-mark">*</span>':''}</label>${input}</div>`;
}
function repeatRow(kind,index,c,value={}){if(kind==='sourceRows')return `<div class="op-repeat-row"><label>منبع<select name="source.${index}.packetId" required>${sourcePackets(c.state,c.actor,c.tasks).filter(p=>!['consumed','outside'].includes(p.state)&&p.mass!==null).map(p=>`<option value="${p.id}">${esc(p.id+' · '+p.form+' · '+grams(p.mass)+' گرم')}</option>`).join('')}</select></label><label>وزن واقعی از همین منبع · گرم<input name="source.${index}.mass" inputmode="decimal" required></label></div>`;if(kind==='outputRows')return `<div class="op-repeat-row"><label>فلز<select name="output.${index}.metal"><option>نقره</option><option>طلا</option></select></label><label>شکل خروجی<input name="output.${index}.form" required></label><label>وزن واقعی · گرم<input name="output.${index}.mass" inputmode="decimal" required></label><label>عیار · اختیاری<input name="output.${index}.purity" inputmode="decimal"></label><label>محل واقعی<input name="output.${index}.place" required></label></div>`;if(kind==='invoiceRows')return `<div class="op-repeat-row" data-row="${index}"><label>شرح ردیف<input name="line.${index}.title" value="${esc(value.title||'')}" required></label><label>تعداد<input name="line.${index}.quantity" value="${esc(value.quantity||'')}" inputmode="decimal" required></label><label>واحد<select name="line.${index}.unit">${['عدد','جفت','بسته','کیلوگرم','گرم','لیتر','متر','خدمت'].map(unit=>`<option ${unit===value.unit?'selected':''}>${unit}</option>`).join('')}</select></label><label>قیمت واحد · ریال<input name="line.${index}.unitPrice" value="${esc(value.unitPrice||'')}" inputmode="decimal" required></label></div>`;return `<div class="op-repeat-row" data-row="${index}"><label>عکس مستقل این قلم<input type="file" name="item.${index}.photo" accept="image/*" capture="environment" required></label><label>مبنای جرم<select name="item.${index}.massBasis"><option value="solid">جامد</option><option value="wet">تر / محلول</option><option value="dry">خشک</option></select></label><label>فلز<select name="item.${index}.metal"><option>نقره</option><option>طلا</option></select></label><label>شکل بار<select name="item.${index}.form">${['آب‌شده','قرص','ظروف','ساچمه','شمش','محلول','فیلتر','سایر'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>وزن اعلامی طرف · گرم<input name="item.${index}.declared" inputmode="decimal"></label><label>وزن با بسته اعلامی · گرم<input name="item.${index}.declaredGross" inputmode="decimal"></label><label>وزن واقعی با بسته · گرم<input name="item.${index}.gross" inputmode="decimal" required></label><label>وزن واقعی بدون بسته · گرم<input name="item.${index}.net" inputmode="decimal" required></label><label>وضعیت عیار<select name="item.${index}.certainty"><option value="unknown">نامشخص</option><option value="declared">اعلامی / شرطی</option><option value="measured">اندازه‌گیری‌شده</option></select></label><label>عیار · در هزار<input name="item.${index}.purity" inputmode="decimal"></label><label>کار شرطی مستقل<select name="item.${index}.conditional"><option value="no">خیر</option><option value="yes">بله</option></select></label></div>`;}
export function openFactoryForm(command,c,d={}){
 d.operationId||=uid('submit');const fields=formSchema(command,c,d),t=d.taskId?c.tasks.find(t=>t.id===d.taskId):null;
 const title={'attendance-in':'ثبت ورود','attendance-out':'ثبت خروج','hr-request':'درخواست شخصی',expense:'ثبت خرید','expense-edit':'ویرایش خرید',consume:'ثبت مصرف مواد',receive:'رسید ورود چندقلمی',admit:'پذیرش و مرجوعی قلم',reserve:'رزرو مواد برای همین کار',handover:'تحویل دوطرفه',report:'گزارش مرحله','task-edit':'ویرایش کار جاری با سابقه','approve-task':'تصمیم درباره درخواست','hr-dossier':'پرونده خصوصی فرد','payment-record':'ثبت پرداخت انجام‌شده در نمونه','package-void':'ابطال بسته‌بندی با حفظ کالا'}[command]||'ثبت '+(factoryRoutes[c.route]||'رویداد');
 const record=d.id?(s=>s.payments.find(x=>x.id===d.id)||s.hrRequests.find(x=>x.id===d.id)||s.assays.find(x=>x.id===d.id)||s.expenses.find(x=>x.id===d.id)||s.tools.find(x=>x.id===d.id)||s.devices.find(x=>x.id===d.id)||s.recoveries.find(x=>x.id===d.id)||{})(c.state):{};
 const initial={...(t||{}),...record,...(record.requestedCommands?{commands:record.requestedCommands.join(',')}:{}),...(command==='hr-dossier'&&d.userId?c.state.dossiers[d.userId]||{}:{}),...d};if(command==='hr-dossier'&&d.userId)initial.salary=c.state.dossiers[d.userId]?.fixedSalary;
 c.modal(title,`<form id="factory-form" data-command="${command}" data-props="${esc(JSON.stringify(d))}" novalidate><div class="form-error" role="alert" id="factory-error"></div>${record.name?row('دریافت‌کننده',record.name)+row('مبلغ',money(record.amount)):''}${command==='payment-record'&&!canSettlePayment(c.state,c.actor,record)?'<div class="op-warning">سقف تعیین نشده یا مبلغ خارج از سقف است؛ تأیید علیرضا یا بهنام لازم است.</div>':''}${fields.length?fields.map(f=>fieldMarkup(f,c,initial[f.key])).join(''):'<p>این رویداد با حساب فعلی و زمان ثبت، به تاریخچه اضافه می‌شود.</p>'}</form>`,`<button class="primary" form="factory-form" type="submit">${command==='consume'?'ثبت مصرف':command==='hr-request'?'ارسال درخواست':'ثبت'}</button>`,true);
 const el=document.getElementById('factory-form');
 if(command==='consume'){
  const select=el.elements.supplyId,label=el.querySelector('[for="op-quantity"]');
  const sync=()=>{const supply=c.state.supplies.find(item=>item.id===select.value);label.textContent=supply?'مقدار · '+supply.unit:'مقدار';};
  select.addEventListener('change',sync);sync();bindPhotoReader(el,true);
 }
 if(['expense','expense-edit'].includes(command)){
  bindPhotoReader(el);
  const cash=c.state.cashRequests.filter(r=>r.actor===c.actor&&r.state==='received');
  if(command==='expense'&&cash.length){
   const field=fieldMarkup({key:'cashRequestId',label:'تنخواه مرتبط',kind:'select',options:cash.map(r=>option(r.id,r.purpose))},c,'');
   el.querySelector('[data-repeat-items]').insertAdjacentHTML('beforebegin',field);
  }
 }
 if(command==='hr-request'){
  const sync=()=>{const kind=el.elements.kind.value;
   const fields={'مرخصی':['start','end','reason'],'حضور ویژه':['start','hours','reason'],'وام':['amount','reason'],'مساعده':['amount','reason'],'تنخواه':['amount','reason'],'سایر موارد':['reason']};
   for(const key of ['start','end','hours','amount','reason']){
    const field=el.elements[key],wrap=field.closest('.field'),visible=(fields[kind]||[]).includes(key);
    wrap.hidden=!visible;wrap.style.display=visible?'':'none';
    for(const input of wrap.querySelectorAll('input,select,textarea'))input.disabled=!visible;
   }
  };el.elements.kind.addEventListener('change',sync);sync();
 }
}
export async function submitFactory(form,c){
 const command=form.dataset.command,d={...JSON.parse(form.dataset.props||'{}')},fd=new FormData(form),schema=formSchema(command,c,d);
 try{
  for(const f of schema){if(['receiptRows','invoiceRows','sourceRows','outputRows','scores'].includes(f.kind))continue;if(f.kind==='file'){const file=form.elements.namedItem(f.key)?.files?.[0];d[f.key]=file?await c.fileData(file):null;if(file&&!d[f.key])throw new Error('ذخیره فایل انتخاب‌شده امکان‌پذیر نیست.');}else if(f.kind==='multiselect')d[f.key]=fd.getAll(f.key).filter(Boolean);else if(f.kind==='checkbox')d[f.key]=fd.has(f.key);else d[f.key]=fd.get(f.key);if(f.required&&(d[f.key]===null||d[f.key]===''||Array.isArray(d[f.key])&&!d[f.key].length))throw new Error(f.label+' لازم است.');}
  for(const [prefix,key]of[['item','items'],['line','lines'],['source','sources'],['output','outputs']]){const rows={};for(const[k,v]of fd){if(!k.startsWith(prefix+'.'))continue;const[,i,field]=k.split('.');(rows[i]||={})[field]=v instanceof File&&v.name?await c.fileData(v):v instanceof File?null:v;}if(Object.keys(rows).length)d[key]=Object.values(rows);}
  if(command==='expense'&&fd.has('cashRequestId'))d.cashRequestId=fd.get('cashRequestId');
  if(command==='hr-dossier'){d.scores={};for(const[k,v]of fd)if(k.startsWith('score.')&&v!=='')d.scores[k.slice(6)]=v;}
  if(command==='system-config')d.temporaryExit=d.temporaryUser?[{userId:d.temporaryUser,until:d.temporaryUntil||null}]:c.state.settings.temporaryExit;
  c.apply(command,d);c.closeModal();c.render();
 }catch(e){const error=document.getElementById('factory-error');if(error){error.textContent=translate(e.message);error.scrollIntoView({block:'nearest'});}else c.toast(e.message);}
}
export function factoryAction(el,c){
 const action=el.dataset.factory;if(!action)return false;
 if(action==='currency'){el.classList.toggle('is-open');return true;}
 if(action==='route'){c.nav(el.dataset.route);return true;}
 if(action==='task'){c.nav('task/'+el.dataset.id);return true;}
 if(action==='create'){c.create();return true;}
 if(action==='form'){const d={...el.dataset};delete d.factory;delete d.command;openFactoryForm(el.dataset.command,c,d);return true;}
 if(action==='add-row'){const container=el.closest('.op-repeat').querySelector('[data-repeat-items]');container.insertAdjacentHTML('beforeend',repeatRow(el.dataset.kind,container.children.length,c));return true;}
 if(action==='help'){c.modal('راهنمای '+factoryRoutes[el.dataset.module],`<p>در این بخش، ابتدا رکورد مربوط را انتخاب کنید. هر اقدام با حساب شما و زمان ثبت در تاریخچه می‌ماند. فیلدهای ستاره‌دار لازم‌اند و داده نامعلوم با صفر جایگزین نمی‌شود.</p><p>در صورت نیاز به تأیید فرد دیگر، مرحله بعد فقط پس از پاسخ همان حساب فعال می‌شود. داده‌های این نسخه برای بررسی طراحی نمونه‌اند.</p>`);return true;}
 if(action==='qr'){const url=(c.baseUrl||'')+'#/verify/'+encodeURIComponent(el.dataset.serial)+'/'+encodeURIComponent(el.dataset.event),src=qrImage(url);c.modal('QR همین بسته',`<img src="${src}" class="product-qr" alt="QR رویداد بسته‌بندی"><p dir="ltr" class="qr-url">${esc(url)}</p><p>این کد، آدرس همان بسته را ذخیره می‌کند. داده نمونه جدید تا اتصال سرور فقط در همین مرورگر وجود دارد.</p><a class="secondary" href="${src}" download="moriyati-package-qr.svg">دریافت QR</a>`);return true;}
 if(action==='verify'){c.nav('verify/'+encodeURIComponent(el.dataset.serial)+'/'+encodeURIComponent(el.dataset.event));return true;}
 if(action==='backup'){c.backup();return true;}
 if(action==='restore'){c.restore();return true;}
 return false;
}
